# Two blocks are "adjacent" if they share a column or row

blocks = [(1,7), (1,13), (2,2), (4,4), (4,11), (5,0), (5,8)]

# Group by row
by_row = {}
for r, c in blocks:
    if r not in by_row:
        by_row[r] = []
    by_row[r].append(c)

print("Blocks by row:")
for r in sorted(by_row.keys()):
    print(f"  Row {r}: {sorted(by_row[r])}")

# Adjacent blocks in same row are those with col difference <= 1
def adjacent(b1, b2):
    return abs(b1[0] - b2[0]) <= 1

# Let me count blocks adjacent vertically (same col position)
adj_pairs = []
for i, b1 in enumerate(blocks):
    for b2 in blocks[i+1:]:
        if b1[0] == b2[0] and abs(b1[1] - b2[1]) <= 1:
            adj_pairs.append((b1, b2))

print(f"Vertically adjacent blocks: {adj_pairs}")

# Now check horizontally (same row)
horiz_pairs = []
for i, b1 in enumerate(blocks):
    for b2 in blocks[i+1:]:
        if b1[0] == b2[0]:
            # Same row
            if abs(b1[1] - b2[1]) <= 1:
